using System.Text.Json;using System.Text.RegularExpressions;
namespace GameTranslator.Translation;
/// <summary>Reviewed phrase rules, gated on both English and the observed bad Arabic.</summary>
public static class ReviewedLanguage {
 public sealed record Rule(string Id,string Game,string Phrase,string Bad,string Replacement,string Meaning="");
 public static IReadOnlyList<Rule> Parse(string json){using var doc=JsonDocument.Parse(json);if(!doc.RootElement.TryGetProperty("rules",out var rows))return [];if(rows.GetArrayLength()>100)throw new InvalidDataException("Too many language rules");var output=new List<Rule>();var seen=new HashSet<string>();foreach(var e in rows.EnumerateArray()){var r=new Rule(e.GetProperty("id").GetString()!,e.GetProperty("game").GetString()!,e.GetProperty("source_phrase").GetString()!,e.GetProperty("bad_arabic").GetString()!,e.GetProperty("replacement").GetString()!,e.TryGetProperty("source_meaning",out var meaning)?meaning.GetString()??"":"");if(!e.GetProperty("reviewed").GetBoolean()||string.IsNullOrWhiteSpace(r.Id)||r.Id.Length>80||!seen.Add(r.Id)||string.IsNullOrWhiteSpace(r.Game)||r.Game.Length>200||r.Phrase.Length<4||r.Phrase.Length>160||string.IsNullOrWhiteSpace(r.Bad)||r.Bad.Length>160||string.IsNullOrWhiteSpace(r.Replacement)||r.Replacement.Length>160||r.Meaning.Length>200)throw new InvalidDataException("Invalid language rule");output.Add(r);}return output;}
 private static string Normalize(string text)=>Regex.Replace(text.ToLowerInvariant().Replace('’','\''),@"\s+"," ").Trim();
 public static bool ContainsPhrase(string source,string phrase){source=Normalize(source);phrase=Normalize(phrase);int at=-1;while((at=source.IndexOf(phrase,at+1,StringComparison.Ordinal))>=0){int end=at+phrase.Length;if((at==0||!char.IsLetterOrDigit(source[at-1]))&&(end==source.Length||!char.IsLetterOrDigit(source[end])))return true;}return false;}
 public static string Hints(IReadOnlyList<Rule> rules,string game,string source)=>string.Join("\n",rules.Where(r=>r.Meaning.Length>0&&(r.Game=="*"||CommunityCorrections.GameKey(r.Game)==CommunityCorrections.GameKey(game))&&ContainsPhrase(source,r.Phrase)).Select(r=>$"In this dialogue, '{r.Phrase}' means '{r.Meaning}'.").Distinct().Take(3));
 public static string Apply(IReadOnlyList<Rule> rules,string game,string source,string arabic){foreach(var r in rules)if((r.Game=="*"||CommunityCorrections.GameKey(r.Game)==CommunityCorrections.GameKey(game))&&arabic.Contains(r.Bad,StringComparison.Ordinal)&&ContainsPhrase(source,r.Phrase))arabic=arabic.Replace(r.Bad,r.Replacement,StringComparison.Ordinal);return arabic;}
}
